import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, CORE_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('explicit !!int with signed negative octal resolves', () => {
    assert.strictEqual(load('!!int "-0o10"', { schema: CORE_SCHEMA }), -8);
    assert.strictEqual(load('!!int "-0x10"', { schema: CORE_SCHEMA }), -16);
  });
});

